#!/bin/zsh
# 用法: tools/vn_prompts.sh <key> <表情> -> 生立繪 (normal 無參考基準；其他表情以 normal 當參考)
cd "$(dirname $0)/.."
key=$1; ex=$2
COMMON="Visual novel character sprite, photorealistic cinematic live-action look matching the reference card art (same face, same costume, same realistic AI-actor style). Upright front-facing standing pose, waist-up to knee-up, vertical 2:3 portrait, character fills about 85% of the image height with a little empty space above the head, both hands fully inside the frame and not cropped. Head, shoulders, hips and feet face the same direction toward the viewer; no twisted neck, no looking back, no turning around. Background must be a perfectly flat solid pure magenta #FF00FF everywhere, no shadow, no gradient, no floor, no props behind, no glow or smoke. No text, no watermark."
case $key in
 yutong) D="Young Taiwanese woman, short mint-green bob haircut with bangs and black roots, black round-frame glasses, a dark reddish birthmark around one eye (a harmless congenital skin mark), wearing an orange-red short-sleeve sports T-shirt with black sleeves and black collar trim, and navy-blue athletic shorts; bare legs, knees visible. No robe, no red thread, no white shirt, no accessories." ; R=(src/qimiao-shiguang/assets/ep/ep2-15.jpg src/qimiao-shiguang/assets/ep/ep3-01.jpg src/qimiao-shiguang/assets/c/c044.jpg);;
 lee) D="Thin middle-aged man in a tall black top hat, black suit jacket over a white dress shirt and dark necktie, stern gaunt face; only items shown in the references, no purple lightning, no Qing robe." ; R=(art/lee4.png refs/lee-suit1.jpg refs/lee-suit2.jpg refs/lee-suit-chart.jpg);;
 linbobo) D="Elderly kind uncle in the same outfit and face as the reference card." ; R=(art/linbobo.png);;
 bohong) D="Teenage sprinter with short spiky black hair, wearing a black zip-up athletic track jacket with white stripes and black track pants, exactly like the reference card." ; R=(art/bohong.png);;
 yuelao) D="Same matchmaker deity elder and same outfit as the reference card." ; R=(art/yuelao.png);;
 rat) D="A hamster strategist character, same as the reference card, standing upright on its hind legs." ; R=(art/rat.png);;
 leviathan) D="Young man with silver hair with blue tips, blue glitter makeup on the cheek, black jacket, black headphones hanging around his neck; only items shown in the references, nothing added." ; R=(art/leviathan.png src/qimiao-shiguang/assets/g/c059-1.jpg);;
 yutongh) D="Young Taiwanese woman, straight black bob haircut with full bangs, NO glasses, a red birthmark on one cheek decorated with a few tiny sparkling rhinestones, wearing a pale mint-green and white Hanfu, a small golden hair ornament; only items shown in the references." ; R=(art/yutong4.png src/qimiao-shiguang/assets/ep/ep4-08.jpg refs/yutong-chart.jpg);;
 youshuzhang) D="Handsome clean man with long black hair half tied up and a few white strands beside the face, wearing a white Hanfu with red-and-black patterned trim; clean face, no dirt, no blood; only items shown in the references." ; R=(art/youshuzhang.png src/qimiao-shiguang/assets/g/c052-3.jpg src/qimiao-shiguang/assets/ep/yl-04.jpg);;
 yangzi) D="Young woman with long black hair, a silver hair crown, white Hanfu with flowing black ribbons; only items shown in the references." ; R=(art/yangzi.png work/vn/refs/048.png src/qimiao-shiguang/assets/g/c064-1.jpg);;
 nova) D="Little girl with short black hair, wearing a blue narwhal-shaped hat and a light-blue sleeveless dress; only items shown in the references. Child proportions, full face visible." ; R=(art/nova.png src/qimiao-shiguang/assets/g/c060-1.jpg);;
 liudaniu) D="Qin-dynasty squad leader / prison guard, same man and same outfit as in the references; only items shown in the references." ; R=(art/liudaniu.png src/qimiao-shiguang/assets/g/c053-1.jpg);;
 guanyin) D="Guanyin in a modern look: white suit, silver-purple hair, thin-frame glasses, same as the references; only items shown." ; R=(art/guanyin.png src/qimiao-shiguang/assets/g/c005-3.jpg src/qimiao-shiguang/assets/g/c005-4.jpg);;
 qianliyan) D="General with a green feather mask and feather battle robe, same as the references; only items shown." ; R=(art/qianliyan.png src/qimiao-shiguang/assets/g/c070-1.jpg);;
 baizhu) D="Middle-aged tough man, slicked-back black hair, with a distinctive black spider-web tattoo covering one cheek and temple as in the photo reference (not a scar), wearing a white suit jacket over a black shirt; same as the reference card, nothing added." ; R=(art/baizhu.png src/qimiao-shiguang/assets/g/c092-1.jpg);;
 shushi) D="Elderly Taiwanese shaman-sorcerer exactly like the man on the LEFT of the reference photo: old man with short white hair, white stubble, tanned wrinkled skin, a red cloth blindfold tied over both eyes, bare chest with red-brown layered sash and woven cord belts with charms, red and rust-brown wrapped robe skirts, bead necklaces, cord bracelets, leather sandals, holding a tall wooden staff with red tassels and charms. Match him exactly, nothing added; ignore the young man in the yellow raincoat." ; R=(refs/shushi-ref.png);;
 cherub) D="Calm man with short black hair in a white hooded robe with a gold cross-shaped pendant necklace; same as the reference card, nothing added." ; R=(art/cherub.png);;
 gyxiaoqing) D="Young woman with long blonde hair, a black lace hat and black lace long-sleeve dress, holding a white face mask; same as the reference card, nothing added." ; R=(art/gyxiaoqing.png);;
 lucifer) D="Tall archangel with long white-silver hair and large white wings, black-and-gold ornate armor and cape; same as the reference card, nothing added." ; R=(art/lucifer.png);;
 zhurong) D="Demigod captain with long golden hair, glowing red eyes, black-and-gold armored robe with flame patterns; same as the reference card, nothing added." ; R=(art/zhurong.png);;
 gengyin) D="Elderly matchmaker deity with a long white beard and a golden topknot, red-and-gold embroidered robe, holding red thread and a book; same as the reference card, nothing added." ; R=(art/gengyin.png);;
 huatuo) D="Man in a dark red-brown hooded jacket over a dark tee, a brown knitted beanie, small round green-tinted sunglasses, black over-ear headphones around the neck, a thick gold chain with a gold pendant, a few rings; same face and outfit as the reference card; only items shown in the references." ; R=(work/refs10/huatuo.png work/refs10/s099.png);;
 jiuwei) D="Young woman with a short dark-purple bob haircut, thin round glasses, a white fluffy fur-trim coat; large fluffy blue fox tails visible behind her shoulders; calm cool expression, same as the reference card; only items shown in the references." ; R=(work/refs10/jiuwei.png work/refs10/s195.png work/refs10/s095.png);;
 xiaoyu) D="Young woman with long straight black hair and straight full bangs, wearing a loose cream-white sweatshirt cardigan at home; no apron, no accessories; same face as the reference card; only items shown in the references." ; R=(work/refs10/xiaoyu.png work/refs10/s198.png);;
 dabao) D="Young man with short bleached blonde hair with black streaks on top, wearing a plain black oversized T-shirt and grey sweatpants; same face as the reference card; only items shown in the references; no jacket, no hoodie." ; R=(work/refs10/dabao3.png work/refs10/s198.png work/refs10/s100.png);;
 mimi) D="Young woman with black hair tied in a high ponytail bun with straight bangs, wearing a black sheer lace dress embroidered with small white flowers over a black top, black knee socks and black mary-jane shoes; same face as the reference card; only items shown in the references." ; R=(work/refs10/mimi.png work/refs10/s100.png);;
 huji) D="Young woman in a pink ruffled fluffy dress with a pink cat-ear headband, pink fluffy fox tail behind her, same face and outfit as the reference card; only items shown in the references." ; R=(work/refs10/huji.png work/refs10/s095.png work/refs10/s200.png);;
 xiaomi) D="Young woman city-office receptionist: black bob hair with bangs, thin round glasses, a small headset microphone, grey blazer over a white shirt with a navy bow tie and navy-trimmed lapels; same face and outfit as the reference card; only items shown in the reference, nothing added." ; R=(art/xiaomi.png);;
 gongwan) D="A black cat with an orange-brown leather collar and a round brass name tag, sitting upright facing the viewer, eyes gently closed with a contented smile, same cat as the references; a real cat, not a human; only items shown in the references." ; R=(art/gongwan.png src/qimiao-shiguang/assets/c/c019.jpg);;

 mazu) D="Young woman Mazu: long straight dark brown hair, thin round gold-rimmed glasses, a black flat-topped imperial crown (mianguan) with strands of white, red and light-blue beads hanging in front, red ribbons and red tassels beside her face, long pearl-and-flower earrings, a white high-collared silk robe with gold lotus embroidery, gold flower appliques with pearls on the chest and shoulders, fine gold bead chains across the chest; same as the reference card; only items shown in the references." ; R=(art/mazu.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/媽祖/EP7-03_082.0_半身.jpg);;
 shunfeng) D="Young woman with long straight white-silver hair, a red-and-black knitted beanie, fluffy green fur earmuffs, a dark green knitted scarf pulled up covering her mouth and chin, black fingerless gloves, a black-and-red loose sports jersey with white Chinese characters 順風 printed on the chest, red-and-black cargo pants; same as the reference card; only items shown in the references. Expression shown only through the eyes since the scarf covers her mouth." ; R=(art/shunfeng.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/順風耳/EP7-06_054.0_全身.jpg);;
 xieshou) D="Young man exorcist wearing a green hat shaped like a crab with two big round eyes on top and claws at the sides, a beige-and-green robe with leaf patterns over dark green clothes, a green tassel charm hanging at the neck; same as the reference card; only items shown in the references; no glowing effects." ; R=(art/xieshou.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/謝守/EP7-06_059.7_全身.jpg);;
 renmianyu) D="A character wearing a grey shark-shaped hood with big teeth framing the face, with a golden smiling human-face mask with a small white beard under the shark mouth, a black long-sleeve shirt; no chains, standing upright; same as the reference card; only items shown in the references." ; R=(art/renmianyu.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/人面魚/EP7-06_035.0_全身.jpg);;
 redgirl) D="Young adult woman with long straight black hair, red eyes, thin black crack-like tear streaks on her cheeks, a dark red sleeveless dress and a wide-brim navy-blue hat with white lace trim, blue roses, a white lily and pearl chains; same as the reference card; only items shown in the references." ; R=(art/redgirl.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/紅衣小女孩/EP7-10_067.5_全身.jpg);;
 baifu) D="Deity wearing a Chinese opera white face-paint mask with red and black patterns, a gold crown with a red jewel and flowers, tall black hair buns, red tassels hanging at both sides, a white and gold embroidered robe with white feather-like collar and a crane emblem, red sash with a jade ring; same as the reference card; only items shown in the references." ; R=(art/baifu.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/白府千歲/EP7-09_062.5_全身.jpg);;
 nuwa) D="Goddess Nuwa: young woman with long dark hair, an ornate gold crown with pink jewels and flowers, long pink ribbons and pearl tassels, gold necklace and bracelets, a pink and gold dress; same as the reference card; only items shown in the references." ; R=(art/nuwa.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/女媧/EP6-22_064.5_半身.jpg);;
 isaiah) D="Huge orc warrior with golden-orange skin, two curved horns, black ponytail topknot, goatee, shirtless muscular body with a spiked leather shoulder pauldron and diagonal strap with a round emblem, spiked bracers, a belt with a demon-face buckle and a ragged red skirt; same as the reference card; no mug, no hammer; only items shown in the references." ; R=(art/isaiah.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/以賽亞/EP6-18_063.0_半身.jpg);;
 daogui) D="One-armed green-skinned orc swordsman: white mask covering the face with a red X mark (not a blindfold, eyes uncovered visible through the mask), black ponytail topknot, a torn white robe off one shoulder, a dark sash belt with a katana at the waist and a black tassel, only one arm; same as the reference card; only items shown in the references." ; R=(art/daogui.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/刀鬼/EP6-18_052.0_全身.jpg);;
 mofaweng) D="Old demon-race wizard with blue-grey skin, red rune scars on the face, curved dark ribbed horns, long white-grey hair and white goatee, orange eyes, small gold earring, a dark robe with gold-trimmed patterned collar and shoulders; same as the reference card; only items shown in the references." ; R=(art/mofaweng.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/魔法翁/EP6-18_048.0_半身.jpg);;
 aizen) D="Young man Aizen Myoo, season-six look: blond hair, a red crown with a red mask-like ornament at the front, long white pearl necklaces, a red and gold embroidered robe with gold shoulder pieces, bare chest partly visible, gold bracelets; NO blindfold, eyes fully visible; same as the reference card; only items shown in the references." ; R=(art/aizen.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/愛染明王/EP6-23_074.7_半身.jpg /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/愛染明王/EP6-25_063.0_半身.jpg);;
 dabaof) D="Young man with tousled golden-orange hair with black streaks, wearing a red firefighter turnout coat with yellow and silver reflective stripes on the sleeves and a black shoulder radio microphone clipped to the chest; no extinguisher in hand, arms down; same face and outfit as the reference card; only items shown in the references." ; R=(art/dabao4.png /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/大寶/EP6-24_037.4_半身.jpg /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/大寶/EP6-25_019.0_半身.jpg);;
 guanyin6) D="Woman Guanyin, season-six look: half white and half purple hair (white at the left side, purple at the right, tied back in a ponytail), thin round glasses, red lipstick, a plain black long-sleeve shirt, white trousers; NO blindfold, eyes fully visible; no suit jacket, no halo; only items shown in the references." ; R=(/Users/hermes/Public/0720/1005/劇照/EP105-130/角色/觀音菩薩/EP6-24_084.5_半身.jpg /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/觀音菩薩/EP6-24_084.5_正臉.jpg);;
 yuelao6) D="Handsome young man Yuelao, season-six look: shoulder-length dark brown hair with white streaks at the front, wearing a white long robe with red trim along the collar and front, a red round pendant; clean face; same as the references; only items shown in the references." ; R=(/Users/hermes/Public/0720/1005/劇照/EP105-130/角色/月老/EP6-25_055.5_半身.jpg /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/月老/EP6-26_020.0_半身.jpg /Users/hermes/Public/0720/1005/characters/月老.jpg);;
 yutong7) D="Young Taiwanese woman Yutong, season-seven look: short black bob with full straight bangs, NO glasses, red blush-like birthmark marks on both cheeks with a few tiny dark dots, wearing a cream-white short wool jacket with black buttons over a black high-collar turtleneck; only items shown in the references; nothing added." ; R=(/Users/hermes/Public/0720/1005/劇照/EP105-130/角色/語彤/EP7-04_003.0_半身.jpg /Users/hermes/Public/0720/1005/劇照/EP105-130/角色/語彤/EP7-05_047.0_半身.jpg /Users/hermes/Public/0720/1005/characters/語彤.jpg);;
esac
declare -A E
E[normal]="Calm neutral expression, mouth closed."
E[angry]="Angry expression: furrowed brows, glaring eyes, clenched teeth."
E[sad]="Quiet gentle expression with softly lowered eyelids and a slight downward curve of the mouth, like a wistful goodbye."
E[smile]="Gentle warm smile."
E[pain]="Heavy-hearted aching expression, one hand resting on her chest, brows drawn together, eyes closed, a pained sigh."
E[serious]="Serious solemn expression, firm gaze, mouth closed."
E[smug]="Smug self-satisfied smirk, chin slightly raised."
if [[ $ex == normal ]]; then
  tools/gen.sh vn-$key-normal "$D $COMMON ${E[normal]}" $R
else
  tools/gen.sh vn-$key-$ex "Same exact character, same costume, same pose and framing and same flat magenta background as the first reference image (the base sprite). Only the facial expression changes. $COMMON ${E[$ex]}" work/vn/vn-$key-normal.png $([[ $key == yutong* ]] || echo $R)
fi
mv art/vn-$key-$ex.png work/vn/ 2>/dev/null
